function PageIntro({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: React.ReactNode }) { return <div className="mb-7 flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><p className="eyebrow">{eyebrow}</p><h1 className="mt-2 font-serif text-3xl font-bold tracking-tight sm:text-4xl">{title}</h1><p className="mt-2 max-w-3xl text-base leading-relaxed text-muted-foreground">{description}</p></div>{action}</div> }
function Metric({ label, value, note, icon }: { label: string; value: string; note: string; icon: React.ReactNode }) { return <Card className="gap-3 py-4 shadow-none"><CardContent className="flex items-center gap-4 px-4"><span className="metric-icon">{icon}</span><div><p className="text-sm text-muted-foreground">{label}</p><p className="text-2xl font-bold tracking-tight">{value}</p><p className="text-xs text-muted-foreground">{note}</p></div></CardContent></Card> }
